СтрокаОплаты.СтатьяДвиженияДенежныхСредств = ОбразецСписания.СтатьяДвиженияДенежныхСредств;
СтрокаОплаты.СчетУчетаРасчетовСКонтрагентом = ОбразецСписания.СчетУчетаРасчетовСКонтрагентом;
СтрокаОплаты.СчетУчетаРасчетовПоАвансам = ОбразецСписания.РасшифровкаПлатежа[0].СчетУчетаРасчетовПоАвансам;
СтрокаОплаты.СпособПогашенияЗадолженности = Перечисления.СпособыПогашенияЗадолженности.Автоматически;
СтрокаОплаты.СчетНаОплату = Счет.Ссылка;
СписаниеТабличное.Записать(РежимЗаписиДокумента.Проведение);

СписаниеПрямое = ОбразецСписания.Скопировать();
СписаниеПрямое.Дата = Дата(2026, 9, 6, 12, 0, 0);
СписаниеПрямое.Комментарий = Маркер + "-pay-direct";
СписаниеПрямое.СуммаДокумента = 100;
СписаниеПрямое.ДокументОснование = Счет.Ссылка;
СписаниеПрямое.Контрагент = Счет.Контрагент;
СписаниеПрямое.ДоговорКонтрагента = Счет.ДоговорКонтрагента;
СписаниеПрямое.Организация = Счет.Организация;
СписаниеПрямое.РасшифровкаПлатежа.Очистить();
СтрокаПрямая = СписаниеПрямое.РасшифровкаПлатежа.Добавить();
СтрокаПрямая.ДоговорКонтрагента = Счет.ДоговорКонтрагента;
СтрокаПрямая.СуммаПлатежа = 100;
СтрокаПрямая.КурсВзаиморасчетов = 1;
СтрокаПрямая.КратностьВзаиморасчетов = 1;
СтрокаПрямая.СуммаВзаиморасчетов = 100;
СтрокаПрямая.СтавкаНДС = Перечисления.СтавкиНДС.НДС20;
СтрокаПрямая.СуммаНДС = 16.67;
СтрокаПрямая.СтатьяДвиженияДенежныхСредств = ОбразецСписания.СтатьяДвиженияДенежныхСредств;
СтрокаПрямая.СчетУчетаРасчетовСКонтрагентом = ОбразецСписания.СчетУчетаРасчетовСКонтрагентом;
СтрокаПрямая.СчетУчетаРасчетовПоАвансам = ОбразецСписания.РасшифровкаПлатежа[0].СчетУчетаРасчетовПоАвансам;
СтрокаПрямая.СпособПогашенияЗадолженности = Перечисления.СпособыПогашенияЗадолженности.Автоматически;
СписаниеПрямое.Записать(РежимЗаписиДокумента.Проведение);

СписаниеЦепочка = ОбразецСписания.Скопировать();
СписаниеЦепочка.Дата = Дата(2026, 9, 7, 12, 0, 0);
СписаниеЦепочка.Комментарий = Маркер + "-pay-chain";
СписаниеЦепочка.СуммаДокумента = 50;
СписаниеЦепочка.ДокументОснование = ПоручениеЦепочка.Ссылка;
СписаниеЦепочка.Контрагент = Счет.Контрагент;
СписаниеЦепочка.ДоговорКонтрагента = Счет.ДоговорКонтрагента;
СписаниеЦепочка.Организация = Счет.Организация;
СписаниеЦепочка.РасшифровкаПлатежа.Очистить();
СтрокаЦепочки = СписаниеЦепочка.РасшифровкаПлатежа.Добавить();
СтрокаЦепочки.ДоговорКонтрагента = Счет.ДоговорКонтрагента;
СтрокаЦепочки.СуммаПлатежа = 50;
СтрокаЦепочки.КурсВзаиморасчетов = 1;
СтрокаЦепочки.КратностьВзаиморасчетов = 1;
СтрокаЦепочки.СуммаВзаиморасчетов = 50;
СтрокаЦепочки.СтавкаНДС = Перечисления.СтавкиНДС.НДС20;
СтрокаЦепочки.СуммаНДС = 8.33;
СтрокаЦепочки.СтатьяДвиженияДенежныхСредств = ОбразецСписания.СтатьяДвиженияДенежныхСредств;
СтрокаЦепочки.СчетУчетаРасчетовСКонтрагентом = ОбразецСписания.СчетУчетаРасчетовСКонтрагентом;
СтрокаЦепочки.СчетУчетаРасчетовПоАвансам = ОбразецСписания.РасшифровкаПлатежа[0].СчетУчетаРасчетовПоАвансам;
СтрокаЦепочки.СпособПогашенияЗадолженности = Перечисления.СпособыПогашенияЗадолженности.Автоматически;
СписаниеЦепочка.Записать(РежимЗаписиДокумента.Проведение);

РезультатВыполнения = Новый Структура;
РезультатВыполнения.Вставить("Маркер", Маркер);
РезультатВыполнения.Вставить("Счет", Строка(Счет.Ссылка.УникальныйИдентификатор()));
РезультатВыполнения.Вставить("СуммаДокумента", Счет.СуммаДокумента);

СчетСсылка = Документы.СчетНаОплатуПоставщика.ПолучитьСсылку(Новый УникальныйИдентификатор("${fixture.result.Счет}"));
ОтчетОбъект = Отчеты.АнализНеоплаченныхСчетовПоставщиков.Создать();
Схема = ОтчетОбъект.СхемаКомпоновкиДанных;
ПараметрПериод = Схема.Параметры.Найти("Период");
ПараметрПериод.Выражение = "";
ПараметрПериод.Значение = КонецДня(ТекущаяДатаСеанса());
Компоновщик = ОтчетОбъект.КомпоновщикНастроек;
Компоновщик.Инициализировать(Новый ИсточникДоступныхНастроекКомпоновкиДанных(Схема));
Компоновщик.ЗагрузитьНастройки(Схема.НастройкиПоУмолчанию);
ГСК5855_ОбщегоНазначения.ВключитьКолонкиОплатыВНастройках(Компоновщик);
Настройки = Компоновщик.ПолучитьНастройки();
ПараметрНастроек = Настройки.ПараметрыДанных.Элементы.Найти("Период");
Если ПараметрНастроек <> Неопределено Тогда
    ПараметрНастроек.Значение = КонецДня(ТекущаяДатаСеанса());
    ПараметрНастроек.Использование = Истина;
КонецЕсли;
Отбор = Настройки.Отбор.Элементы.Добавить(Тип("ЭлементОтбораКомпоновкиДанных"));
Отбор.ЛевоеЗначение = Новый ПолеКомпоновкиДанных("СчетНаОплату");
Отбор.ВидСравнения = ВидСравненияКомпоновкиДанных.Равно;
Отбор.ПравоеЗначение = СчетСсылка;
Отбор.Использование = Истина;
КомпоновщикМакета = Новый КомпоновщикМакетаКомпоновкиДанных;
Макет = КомпоновщикМакета.Выполнить(Схема, Настройки, , , Тип("ГенераторМакетаКомпоновкиДанных"));
Процессор = Новый ПроцессорКомпоновкиДанных;
Процессор.Инициализировать(Макет);
ТабличныйДокумент = Новый ТабличныйДокумент;
Вывод = Новый ПроцессорВыводаРезультатаКомпоновкиДанныхВТабличныйДокумент;
Вывод.УстановитьДокумент(ТабличныйДокумент);
Вывод.Вывести(Процессор);
Если ТабличныйДокумент.ВысотаТаблицы < 2 Тогда
    ВызватьИсключение "Табличный документ отчета пуст";
КонецЕсли;
Колонки = Новый Соответствие;
Для НомерКолонки = 1 По ТабличныйДокумент.ШиринаТаблицы Цикл
    Колонки.Вставить(СокрЛП(ТабличныйДокумент.Область(1, НомерКолонки).Текст), НомерКолонки);
КонецЦикла;
КолонкаДокумента = Колонки.Получить("Сумма документа");
КолонкаОплаты = Колонки.Получить("Сумма оплаты");
КолонкаОстатка = Колонки.Получить("Неоплаченный остаток");
Если КолонкаДокумента = Неопределено Или КолонкаОплаты = Неопределено Или КолонкаОстатка = Неопределено Тогда
    ВызватьИсключение "В шапке отчета нет колонок суммы, оплаты или остатка";
КонецЕсли;
НомерСтрокиДанных = 0;
Для НомерСтроки = 2 По ТабличныйДокумент.ВысотаТаблицы Цикл
    ТекстПервойЯчейки = СокрЛП(ТабличныйДокумент.Область(НомерСтроки, 1).Текст);
    ТекстСуммы = СокрЛП(ТабличныйДокумент.Область(НомерСтроки, КолонкаДокумента).Текст);
    Если ТекстПервойЯчейки <> "Итого" И ЗначениеЗаполнено(ТекстСуммы) Тогда
        НомерСтрокиДанных = НомерСтроки;
    КонецЕсли;
КонецЦикла;
Если НомерСтрокиДанных = 0 Тогда
    ВызватьИсключение "В табличном документе нет строки счета " + Строка(СчетСсылка);
КонецЕсли;
ТекстДокумента = СокрЛП(ТабличныйДокумент.Область(НомерСтрокиДанных, КолонкаДокумента).Текст);
ТекстОплаты = СокрЛП(ТабличныйДокумент.Область(НомерСтрокиДанных, КолонкаОплаты).Текст);
ТекстОстатка = СокрЛП(ТабличныйДокумент.Область(НомерСтрокиДанных, КолонкаОстатка).Текст);
ТекстДокумента = СтрЗаменить(СтрЗаменить(ТекстДокумента, " ", ""), Символ(160), "");
ТекстОплаты = СтрЗаменить(СтрЗаменить(ТекстОплаты, " ", ""), Символ(160), "");
ТекстОстатка = СтрЗаменить(СтрЗаменить(ТекстОстатка, " ", ""), Символ(160), "");
РезультатВыполнения = Новый Структура;
РезультатВыполнения.Вставить("СуммаДокумента", Число(ТекстДокумента));
РезультатВыполнения.Вставить("СуммаОплаты", Число(ТекстОплаты));
РезультатВыполнения.Вставить("НеоплаченныйОстаток", Число(ТекстОстатка));

Маркер = "ГСК5855-тест-${run.id}%";
Имена = Новый Массив;
Имена.Добавить("СписаниеСРасчетногоСчета");
Имена.Добавить("ПлатежноеПоручение");
Имена.Добавить("СчетНаОплатуПоставщика");
Помечено = 0;
Для Каждого ИмяДокумента Из Имена Цикл
    Запрос = Новый Запрос;
    Запрос.Текст = "ВЫБРАТЬ Ссылка ИЗ Документ." + ИмяДокумента + " ГДЕ Комментарий ПОДОБНО &Маркер И НЕ ПометкаУдаления";
    Запрос.УстановитьПараметр("Маркер", Маркер);
    Выборка = Запрос.Выполнить().Выбрать();
    Пока Выборка.Следующий() Цикл
        Объект = Выборка.Ссылка.ПолучитьОбъект();
        Объект.УстановитьПометкуУдаления(Истина);
        Помечено = Помечено + 1;
    КонецЦикла;
КонецЦикла;
РезультатВыполнения = Помечено;
